 152	    pub fn set_enabled(&mut self, enabled: bool) {
 153	        if self.enabled && !enabled {
 154	            self.pending_on.clear();
 155	            self.pending_off.clear();
 156	            self.flush_species4();
 157	            self.held.clear();
 158	            self.state.reset();
