 164	    pub fn set_species(&mut self, species: CounterpointSpecies) {
 165	        if self.species != species {
 166	            self.pending_on.clear();
 167	            self.flush_species4();
 168	            self.held.clear();
 169	            self.cantus_history.clear();
 170	            self.species = species;
 171	            // Resetting the state on species change so the new species
 172	            // doesn't inherit history that was scored under the old
 173	            // species' rules.
 174	            self.state.reset();
 175	            self.state.set_species(species);
 176	        }
 177	    }
