 206	    fn insert_pending(&mut self, p: PendingCpOn) {
 207	        let pos = self
 208	            .pending_on
 209	            .iter()
 210	            .rposition(|existing| existing.fire_at <= p.fire_at);
 211	        match pos {
 212	            Some(idx) => self.pending_on.insert(idx + 1, p),
 213	            None => self.pending_on.push_front(p),
 214	        }
 215	    }
