 217	    fn is_consonant(a: u8, b: u8) -> bool {
 218	        matches!(a.abs_diff(b) % 12, 0 | 3 | 4 | 7 | 8 | 9)
 219	    }
 220	
 221	    fn is_species4_dissonance(a: u8, b: u8) -> bool {
 222	        matches!(a.abs_diff(b) % 12, 1 | 2 | 5 | 10 | 11)
 223	    }
