 234	    fn species4_preparation(
 235	        &mut self,
 236	        scale: &mut contrapunk_harmony::Scale,
 237	        melody: Note,
 238	    ) -> Option<Note> {
 239	        let configured = if self.transpose_degrees == 0 {
 240	            Some(melody)
 241	        } else {
 242	            scale.harmonize_smart(melody, self.transpose_degrees, self.prefer_above)
 243	        };
 244	        configured
 245	            .filter(|candidate| Self::is_consonant(u8::from(melody), u8::from(*candidate)))
 246	            .or_else(|| self.pick_pitch(scale, melody))
 247	            .filter(|candidate| Self::is_consonant(u8::from(melody), u8::from(*candidate)))
 248	    }
