 250	    fn arm_species4(
 251	        &mut self,
 252	        scale: &mut contrapunk_harmony::Scale,
 253	        melody: Note,
 254	        velocity: u8,
 255	        channel: u8,
 256	        now: f64,
 257	    ) {
 258	        let Some(preparation) = self.species4_preparation(scale, melody) else {
 259	            self.species4 = None;
 260	            return;
 261	        };
 262	        let prepare_at = Self::next_weak_beat(now);
 263	        self.species4 = Some(Species4Gesture {
 264	            owner_note: u8::from(melody),
 265	            owner_channel: channel,
 266	            pitch: u8::from(preparation),
 267	            velocity,
 268	            prepare_at,
 269	            strong_at: prepare_at + 0.5,
 270	            release_by: None,
 271	            stage: Species4Stage::Armed,
 272	        });
 273	    }
