 275	    fn on_species4_note_on(
 276	        &mut self,
 277	        scale: &mut contrapunk_harmony::Scale,
 278	        melody: Note,
 279	        velocity: u8,
 280	        channel: u8,
 281	        now: f64,
 282	    ) -> LaneOutput {
 283	        let Some(mut gesture) = self.species4.take() else {
 284	            self.arm_species4(scale, melody, velocity, channel, now);
 285	            return LaneOutput::default();
 286	        };
 287	
 288	        let mut ops = Vec::new();
 289	        match gesture.stage {
 290	            Species4Stage::Armed => {
 291	                // The preparation has not sounded, so the newest live
 292	                // note can replace it without any cleanup.
 293	                self.arm_species4(scale, melody, velocity, channel, now);
 294	            }
 295	            Species4Stage::Prepared => {
 296	                let on_expected_strong = (now - gesture.strong_at).abs() <= SPECIES4_STRONG_WINDOW;
 297	                let melody_midi = u8::from(melody);
 298	                let consonant = Self::is_consonant(gesture.pitch, melody_midi);
 299	                let resolution = Note::try_from(gesture.pitch)
 300	                    .ok()
 301	                    .and_then(|pitch| scale.transpose_diatonic(pitch, -1));
 302	
 303	                let resolution =
 304	                    resolution.filter(|note| Self::is_consonant(u8::from(*note), melody_midi));
 305	                match (
 306	                    on_expected_strong && channel == gesture.owner_channel,
 307	                    consonant,
 308	                    resolution,
 309	                ) {
 310	                    (true, false, Some(resolution))
 311	                        if Self::is_species4_dissonance(gesture.pitch, melody_midi) =>
 312	                    {
 313	                        gesture.owner_note = melody_midi;
 314	                        gesture.velocity = velocity;
 315	                        gesture.release_by = None;
 316	                        gesture.stage = Species4Stage::Suspended {
 317	                            resolution: u8::from(resolution),
 318	                            resolve_at: gesture.strong_at + 0.5,
 319	                        };
 320	                        self.species4 = Some(gesture);
 321	                    }
 322	                    (true, true, _) => {
 323	                        // A legal consonant syncopation, not a suspension.
 324	                        // Keep it as the preparation for the next strong beat.
 325	                        gesture.owner_note = melody_midi;
 326	                        gesture.velocity = velocity;
 327	                        gesture.release_by = None;
 328	                        gesture.strong_at += 1.0;
 329	                        self.species4 = Some(gesture);
 330	                    }
 331	                    _ => {
 332	                        // Release before the new live NoteOn is dispatched;
 333	                        // an arbitrary unprepared dissonance must never sound.
 334	                        ops.push(DispatchOp::NoteOff {
 335	                            target: self.voice_output,
 336	                            note: gesture.pitch,
 337	                            channel: gesture.owner_channel,
 338	                        });
 339	                        self.arm_species4(scale, melody, velocity, channel, now);
 340	                    }
 341	                }
 342	            }
 343	            Species4Stage::Suspended { .. } => {
 344	                // Another melody change before the planned resolution
 345	                // invalidates the pre-checked sonority.
 346	                ops.push(DispatchOp::NoteOff {
 347	                    target: self.voice_output,
 348	                    note: gesture.pitch,
 349	                    channel: gesture.owner_channel,
 350	                });
 351	                self.arm_species4(scale, melody, velocity, channel, now);
 352	            }
 353	        }
 354	
 355	        LaneOutput {
 356	            ops,
 357	            ..Default::default()
 358	        }
 359	    }
