 361	    fn flush_species4(&mut self) {
 362	        let Some(gesture) = self.species4.take() else {
 363	            return;
 364	        };
 365	        if gesture.stage != Species4Stage::Armed {
 366	            self.pending_off.push_back(PendingCpOff {
 367	                fire_at: 0.0,
 368	                note: gesture.pitch,
 369	                channel: gesture.owner_channel,
 370	            });
 371	        }
 372	    }
 373	}
