 179	    /// Compute the harmony pitch for the player's input using the
 180	    /// scoring rules baked into CounterpointState.
 181	    fn pick_pitch(&mut self, scale: &mut contrapunk_harmony::Scale, melody: Note) -> Option<Note> {
 182	        // process_directed updates state and returns [melody, harmony].
 183	        let result = self
 184	            .state
 185	            .process_directed(scale, melody, self.prefer_above);
 186	        if result.len() > 1 {
 187	            Some(result[1])
 188	        } else {
 189	            None
 190	        }
 191	    }
