 193	    /// Pick a stepwise neighbour pitch (one diatonic step away from
 194	    /// `from`) for use as a weak-beat passing/auxiliary tone in
 195	    /// Species 2/3. Falls back to `from` if the scale's bounds reject
 196	    /// the step.
 197	    fn pick_passing(
 198	        &self,
 199	        scale: &mut contrapunk_harmony::Scale,
 200	        from: Note,
 201	        direction: i8,
 202	    ) -> Note {
 203	        scale.transpose_diatonic(from, direction).unwrap_or(from)
 204	    }
