 567	                        }
 568	                        HoldMode::Forever => Some(match gesture.stage {
 569	                            Species4Stage::Suspended { resolve_at, .. } => resolve_at + 1.0,
 570	                            _ => gesture.strong_at + 0.5,
 571	                        }),
 572	                    };
