 602	                let global_hold = world
 603	                    .global_hold_mode
 604	                    .lock()
 605	                    .map(|g| *g)
 606	                    .unwrap_or_default();
 607	                let effective = self.hold_mode.unwrap_or(global_hold);
 608	                let beats_per_bar = world.transport.time_signature().0 as f64;
 609	                // PhraseEnd horizon: same idea as CanonLane — let
 610	                // pending emissions within the current bar fire.
 611	                let phrase_end = (now / beats_per_bar).floor() * beats_per_bar + beats_per_bar;
 612	
 613	                // Decide which pending NoteOns for this player note
 614	                // get cancelled vs let-fire, per the effective mode.
 615	                let mut canceled_pitches: Vec<u8> = Vec::new();
 616	                self.pending_on.retain(|p| {
 617	                    if p.player_note != note {
 618	                        return true;
 619	                    }
 620	                    let keep = match effective {
 621	                        HoldMode::Forever => true,
 622	                        HoldMode::Cancel => false,
 623	                        HoldMode::NearFuture { tail_beats } => (p.fire_at - now) <= tail_beats,
 624	                        HoldMode::PhraseEnd => p.fire_at <= phrase_end,
 625	                    };
 626	                    if !keep {
 627	                        canceled_pitches.push(p.note);
 628	                    }
 629	                    keep
 630	                });
 631	                if let Some(mut held) = self.held.remove(&note) {
 632	                    // Cancelled NoteOns get no matching NoteOff — they
 633	                    // never produced sound. Already-emitted notes get
 634	                    // released at `now`, OR at `now + tail_beats` so
 635	                    // the lookahead / sustain semantics feel coherent.
 636	                    held.emitted_notes.retain(|n| !canceled_pitches.contains(n));
 637	                    let release_at = match effective {
 638	                        HoldMode::NearFuture { tail_beats } => now + tail_beats,
 639	                        _ => now,
 640	                    };
 641	                    for n in held.emitted_notes {
 642	                        self.pending_off.push_back(PendingCpOff {
 643	                            fire_at: release_at,
 644	                            note: n,
 645	                            channel: held.channel,
 646	                        });
 647	                    }
 648	                }
 649	            }
 650	            InputEvent::Cc { .. } => {}
 651	        }
