 656	    fn tick(&mut self, world: &WorldState) -> LaneOutput {
 657	        let now = world.transport.total_beats();
 658	        let mut ops: Vec<DispatchOp> = Vec::new();
 659	
 660	        // Cleanup queued by disable/species changes must drain even
 661	        // after the lane gate closes.
 662	        let mut idx = 0;
 663	        while idx < self.pending_off.len() {
 664	            if self.pending_off[idx].fire_at <= now {
 665	                let p = self.pending_off.remove(idx).unwrap();
 666	                ops.push(DispatchOp::NoteOff {
 667	                    target: self.voice_output,
 668	                    note: p.note,
 669	                    channel: p.channel,
 670	                });
 671	            } else {
 672	                idx += 1;
 673	            }
 674	        }
 675	
 676	        // A host seek/loop can move total_beats backwards. Release the
 677	        // sounding gesture and discard every old deadline before any
 678	        // event can reappear on the new timeline.
 679	        if self
 680	            .last_tick_beat
 681	            .map(|previous| now + f64::EPSILON < previous)
 682	            .unwrap_or(false)
 683	        {
 684	            if let Some(gesture) = self.species4.take() {
 685	                if gesture.stage != Species4Stage::Armed {
 686	                    ops.push(DispatchOp::NoteOff {
 687	                        target: self.voice_output,
 688	                        note: gesture.pitch,
 689	                        channel: gesture.owner_channel,
 690	                    });
 691	                }
 692	            }
 693	            self.pending_on.clear();
 694	            self.held.clear();
 695	        }
 696	        self.last_tick_beat = Some(now);
 697	
 698	        if !self.enabled {
 699	            return LaneOutput {
 700	                ops,
 701	                ..Default::default()
 702	            };
 703	        }
 704	
 705	        if let Some(mut gesture) = self.species4.take() {
 706	            if gesture.release_by.map(|at| now >= at).unwrap_or(false) {
 707	                if gesture.stage != Species4Stage::Armed {
 708	                    ops.push(DispatchOp::NoteOff {
 709	                        target: self.voice_output,
 710	                        note: gesture.pitch,
 711	                        channel: gesture.owner_channel,
 712	                    });
 713	                }
 714	            } else {
 715	                match gesture.stage {
 716	                    Species4Stage::Armed if now >= gesture.prepare_at => {
 717	                        if now <= gesture.prepare_at + SPECIES4_LATE_PREPARATION {
 718	                            ops.push(DispatchOp::NoteOn {
 719	                                target: self.voice_output,
 720	                                note: gesture.pitch,
 721	                                velocity: gesture.velocity,
 722	                                channel: gesture.owner_channel,
 723	                            });
