 725	                            self.species4 = Some(gesture);
 726	                        }
 727	                    }
 728	                    Species4Stage::Prepared if now >= gesture.strong_at + 0.5 => {
 729	                        // No new cantus arrived near the expected strong
 730	                        // beat. End the consonant syncopation on the weak
 731	                        // boundary instead of inventing a suspension.
 732	                        ops.push(DispatchOp::NoteOff {
