#[derive(Default)]
pub struct LaneOutput {
    pub ops: Vec<DispatchOp>,
    pub engine_mutations: Vec<EngineMutation>,
    pub world_writes: Vec<WorldWrite>,
    pub suppress_default: bool,
}

